"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[9472],{81253:e=>{e.exports=JSON.parse('{"tag":{"label":"Urban & Transportation","permalink":"/science/tags/urban-transportation","allTagsPath":"/science/tags","count":5,"items":[{"id":"2023/rideshare-detection","title":"Rideshare Sticker Detector","description":"rideshare oppurtunity","permalink":"/science/2023/rideshare-detection"},{"id":"2023/social-distancing","title":"Social Distancing","description":"My name is Ori Zur and I am a rising junior at Northwestern University studying computer science and music composition. This summer at Argonne, I sought to answer the following question: how well are people following social distancing guidelines in outdoor urban environments?","permalink":"/science/2023/social-distancing"},{"id":"2025/traffic-counter","title":"Traffic Counting","description":"NOTE: This document is based on the version 1.0.3 of the traffic counter application.","permalink":"/science/2025/traffic-counter"},{"id":"2023/traffic-state-estimation","title":"Traffic State Estimation","description":"A real-time vehicle tracking application based on deep neural networks was utilized to calculate traffic state. The deep neural networks that were utilized for the estimation were introduced in the \u2018Vehicle Tracking\u2019 post. The traffic state has been calculated by \u2018traffic flow = traffic speed x traffic density\u2019 (traffic_char1996, edie1963). With the equation, we need to measure two of the parameters using instruments for each parameters to estimate the third state. However, on the other hand, the application introduced in this study based on deep neural networks can calculate traffic state independently using a video source.","permalink":"/science/2023/traffic-state-estimation"},{"id":"2023/vehicle-tracking","title":"Vehicle Tracking","description":"Hi there!","permalink":"/science/2023/vehicle-tracking"}],"unlisted":false}}')}}]);